#include <iostream>
#include <string>
#include <vector>
#include <functional>
#include <sstream>

// ---------------- 极简单元测试框架（本章自研） ----------------
// 目标：不依赖 googletest，用 60 行说明「测试框架到底做了什么」：
// ① 用例注册（宏 + 全局注册表）② 断言计数 ③ 失败定位 ④ 汇总与退出码语义
namespace mini {

struct Stats { int tests = 0, failed_tests = 0, checks = 0, failed_checks = 0; };

class Registry {
public:
    static Registry& instance() { static Registry r; return r; }

    void add(const std::string& name, std::function<void()> fn) {
        cases_.push_back(Case{name, std::move(fn)});
    }

    int run() {
        for (auto& c : cases_) {
            std::cout << "[ RUN  ] " << c.name << "\n";
            int before = st_.failed_checks;
            c.fn();
            ++st_.tests;
            if (st_.failed_checks > before) {
                ++st_.failed_tests;
                std::cout << "[ FAIL ] " << c.name << "\n";
            } else {
                std::cout << "[  OK  ] " << c.name << "\n";
            }
        }
        std::cout << "[SUMMARY] 用例=" << st_.tests << " 失败用例=" << st_.failed_tests
                  << " 断言=" << st_.checks << " 失败断言=" << st_.failed_checks << "\n";
        std::cout << "[CI] 退出码语义=" << (st_.failed_checks ? 1 : 0) << "\n";
        return st_.failed_checks ? 1 : 0;
    }

    void check(bool ok, int line, const std::string& msg) {
        ++st_.checks;
        if (!ok) {
            ++st_.failed_checks;
            std::cout << "[ ASSERT ] 第" << line << "行: " << msg << "\n";
        }
    }

    template <typename A, typename B>
    void eq(const A& a, const B& b, int line, const char* ea, const char* eb) {
        std::ostringstream os;
        if (!(a == b)) os << ea << " == " << eb << " 期望=" << b << " 实得=" << a;
        check(a == b, line, os.str());
    }

private:
    struct Case { std::string name; std::function<void()> fn; };
    std::vector<Case> cases_;
    Stats st_;
};

struct Registrar {
    Registrar(const char* n, std::function<void()> fn) {
        Registry::instance().add(n, std::move(fn));
    }
};

}  // namespace mini

#define TEST(name)                                            \
    static void name();                                       \
    static mini::Registrar mini_reg_##name(#name, name);       \
    static void name()

#define CHECK_EQ(a, b) mini::Registry::instance().eq((a), (b), __LINE__, #a, #b)
#define CHECK_TRUE(x)  mini::Registry::instance().check(static_cast<bool>(x), __LINE__, #x)
#define MINI_MAIN()    int main() { return mini::Registry::instance().run(); }

static int g_setup = 0, g_teardown = 0;

// ---------------- 夹具（fixture）：每个用例一个全新实例 ----------------
struct CounterFixture {
    int value = -1;                       // 故意给个"脏"初始值，验证 SetUp 一定被调用
    void SetUp() { ++g_setup; value = 0; }
    void TearDown() { ++g_teardown; }
};

#define TEST_F(Fx, name)                                                          \
    static void name(Fx& self);                                                    \
    static mini::Registrar mini_freg_##name(#name, [] {                             \
        Fx self;                                                                    \
        self.SetUp();                                                               \
        name(self);                                                                 \
        self.TearDown();                                                            \
    });                                                                             \
    static void name(Fx& self)

TEST_F(CounterFixture, add_once) {
    self.value += 5;
    CHECK_EQ(self.value, 5);
    CHECK_EQ(g_setup, 1);            // 本用例执行时 SetUp 恰好被调用过 1 次
}
TEST_F(CounterFixture, add_twice) {
    self.value += 5;
    self.value += 5;
    CHECK_EQ(self.value, 10);        // 若共享实例，这里会读到上一用例的残留
    CHECK_EQ(g_setup, 2);
}
TEST_F(CounterFixture, fresh_after_dirty) {
    CHECK_EQ(self.value, 0);         // 新实例 + SetUp 复位
    CHECK_EQ(g_setup, 3);
}

// 反例：不用夹具、改用跨用例共享的静态状态 -> 第二次"执行"必然失败
TEST(shared_state_leak_demo) {
    static int shared_total = 0;     // BUG 模式：静态状态会跨用例累积
    shared_total += 5;
    CHECK_EQ(shared_total, 5);       // 第一次执行通过
    shared_total += 5;               // 模拟"第二个用例"接着跑
    CHECK_EQ(shared_total, 5);       // 失败：实得 10
}

int main() {
    int rc = mini::Registry::instance().run();
    std::cout << "[FIXTURE] SetUp 调用=" << g_setup << " TearDown 调用=" << g_teardown
              << " 用例各得独立实例=" << (g_setup == g_teardown ? "True" : "False") << "\n";
    return rc;
}
